38	// availableMirrorColumns is the view of a repo you *could* mirror: the
39	// scannable repo name, your effective GitHub access, and whether it's
40	// onboardable. STATUS is "available" (run `entire repo mirror create` to
41	// onboard), "mirrored" (already done — `entire repo mirror list` shows the
42	// clone URL), or "owner-only" (a personal repo of another user; only its
43	// owner may mirror it). No clone URL column: an un-onboarded repo doesn't
44	// have one yet.
45	var availableMirrorColumns = []string{"REPO", "ACCESS", "STATUS"}
46	
47	func availableMirrorRow(m coreapi.AvailableMirror) []string {
48		return []string{m.Owner + "/" + m.Repo, string(m.Access), string(m.Status)}
49	}
