133	func newRepoMirrorCreateCmd() *cobra.Command {
134		var (
135			noWait      bool
136			waitTimeout time.Duration
137		)
138		cmd := &cobra.Command{
139			Use:   "create <github-url> [cluster-host]",
140			Short: "Register a GitHub mirror on a cluster",
141			Long: "Registers a mirror placement for a GitHub repo on the target " +
142				"cluster, then waits for the initial GitHub→EntireDB clone to " +
143				"finish so `git clone` works on return. Pass --no-wait to return " +
144				"as soon as the placement is registered. Idempotent on " +
145				"(upstream, cluster). The cluster-host defaults to " +
146				defaultClusterHost + " when omitted.",
147			Example: "  entire repo mirror create github.com/octocat/hello-world\n" +
148				"  entire repo mirror create github.com/octocat/hello-world eu-west-1.entire.io",
149			Args: cobra.RangeArgs(1, 2),
150			RunE: func(cmd *cobra.Command, args []string) error {
151				owner, repo, err := parseGitHubURL(args[0])
152				if err != nil {
153					cmd.SilenceUsage = true
154					return fmt.Errorf("invalid <github-url>: %w", err)
155				}
156				clusterHost := clusterArg(args)
157				if err := validateClusterHost(clusterHost); err != nil {
158					cmd.SilenceUsage = true
159					return fmt.Errorf("invalid [cluster-host]: %w", err)
160				}
161				return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
162					created, err := c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
163						Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
164						Owner:       owner,
165						Repo:        repo,
166						ClusterHost: clusterHost,
167					})
168					if err != nil {
169						return err
170					}
171					out := cmd.OutOrStdout()
172					repoSlug := "/gh/" + owner + "/" + repo
173					return finishMirrorCreate(out, cmd.ErrOrStderr(), created, noWait,
174						func() error {
175							if _, terr := auth.RepoScopedToken(ctx, clusterHost, repoSlug, "pull"); terr != nil {
176								return fmt.Errorf("probe mirror for suspension: %w", terr)
177							}
178							return nil
179						},
180						func() error {
181							return waitForMirrorClone(ctx, out, clusterHost, owner, repo, waitTimeout)
182						},
183					)
184				})
185			},
186		}
187		cmd.Flags().BoolVar(&noWait, "no-wait", false, "return once the placement is registered, without waiting for the initial clone")
188		cmd.Flags().DurationVar(&waitTimeout, "wait-timeout", 30*time.Minute, "how long to wait for the initial clone to finish")
189		return cmd
190	}
191	
192	// finishMirrorCreate prints the post-create status for `repo mirror create`
193	// and, unless noWait, makes sure the mirror is usable before returning.
194	//
195	// Empty upstream and suspended placement interact. An empty upstream has no
196	// clone to wait for, so the HEAD-poll loop is skipped — it could only spin to
197	// the timeout, since an empty repo never advertises a HEAD. But an *existing*
198	// placement can be suspended even when its upstream is empty, and the
199	// repo-scoped token exchange is the only signal that surfaces that; a *fresh*
200	// create can't be suspended (suspension follows upstream access loss), so it
201	// needs neither the probe nor the wait. Non-empty mirrors take the normal
202	// clone-wait path.
203	//
204	// probeSuspended mints a repo-scoped pull token and returns its error for
205	// explainSuspendedMirror to classify; waitClone runs the HEAD-poll loop. Both
206	// are injected so the branching is unit-testable without the auth and
207	// control-plane stack the production caller wires up.
208	func finishMirrorCreate(out, errW io.Writer, created *coreapi.CreatedMirror, noWait bool, probeSuspended, waitClone func() error) error {
209		if created.Created {
210			fmt.Fprintf(out, "Registered mirror %s\n", created.MirrorId)
211		} else {
212			fmt.Fprintf(out, "Mirror already exists (%s)\n", created.MirrorId)
213		}
214		fmt.Fprintf(out, "  %s\n", created.MirrorUrl)
215	
216		if created.Empty {
217			// An existing placement can sit behind a suspension even with an empty
218			// upstream, so probe the token exchange to surface it. A fresh create
219			// can't be suspended, so skip the probe there.
220			if !created.Created {
221				if err := probeSuspended(); err != nil {
222					if handled, serr := explainSuspendedMirror(errW, created.MirrorId, created.Created, err); handled {
223						return serr
224					}
225					// A non-suspension probe error isn't fatal: the placement exists
226					// and the upstream is genuinely empty, so report that rather than
227					// failing the create on a transient token hiccup.
228				}
229			}
230			fmt.Fprintln(out, "Upstream has no commits yet — nothing to clone. The mirror will pick up refs once the upstream is pushed to.")
231			return nil
232		}
233	
234		if noWait {
235			fmt.Fprintf(out, "Initial clone may still be in progress; `git clone %s` will work once it completes.\n", created.MirrorUrl)
236			return nil
237		}
238		if err := waitClone(); err != nil {
239			if handled, serr := explainSuspendedMirror(errW, created.MirrorId, created.Created, err); handled {
240				return serr
241			}
242			return err
243		}
244		fmt.Fprintf(out, "\nClone it:\n  git clone %s\n", created.MirrorUrl)
245		return nil
246	}
