248	func newRepoMirrorListCmd() *cobra.Command {
249		var cluster, provider, owner string
250		var showAvailable bool
251		cmd := &cobra.Command{
252			Use:   "list",
253			Short: "List mirrors you can see (or, with --show-available, repos you could mirror)",
254			Args:  cobra.NoArgs,
255			RunE: func(cmd *cobra.Command, _ []string) error {
256				if showAvailable {
257					return runCoreList(cmd, availableMirrorColumns, availableMirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.AvailableMirror, error) {
258						// Computed live from GitHub using your own login, so name the
259						// core being dialled (same rationale as the existing-mirror
260						// banner). --cluster/--provider don't apply here: the
261						// onboardable set is cluster-agnostic and GitHub-only.
262						if !jsonRequested(cmd) {
263							fmt.Fprintf(cmd.ErrOrStderr(), "Listing repos you could mirror, via %s\n", c.CoreOrigin())
264						}
265						var params coreapi.ListAvailableMirrorsParams
266						if owner != "" {
267							params.Owner = coreapi.NewOptString(owner)
268						}
269						out, err := c.ListAvailableMirrors(ctx, params)
270						if err != nil {
271							return nil, err
272						}
273						return out.Available, nil
274					})
275				}
276				return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
277					// mirror list is identity-scoped: it shows the mirrors visible
278					// from the active login's federation, so naming that login server
279					// makes a surprising empty result legible — e.g. mirrors in a
280					// different deployment than the active context (--cluster is a
281					// filter, not a router). Name the core the client actually dials
282					// (c.CoreOrigin) so the banner can never diverge from where the
283					// request goes — in particular it reflects ENTIRE_TOKEN's aud,
284					// which a separately-resolved ResolveControlPlaneTarget would miss.
285					// On stderr so it never lands in a piped table; skipped for --json
286					// to keep machine output clean.
287					if !jsonRequested(cmd) {
288						fmt.Fprintf(cmd.ErrOrStderr(), "Listing mirrors on %s\n", c.CoreOrigin())
289					}
290					var params coreapi.ListMirrorsParams
291					if cluster != "" {
292						params.Cluster = coreapi.NewOptString(cluster)
293					}
294					if provider != "" {
295						params.Provider = coreapi.NewOptString(provider)
296					}
297					if owner != "" {
298						params.Owner = coreapi.NewOptString(owner)
299					}
300					out, err := c.ListMirrors(ctx, params)
301					if err != nil {
302						return nil, err
303					}
304					return out.Mirrors, nil
305				})
306			},
307		}
308		cmd.Flags().StringVar(&cluster, "cluster", "", "filter by cluster public host")
309		cmd.Flags().StringVar(&provider, "provider", "", "filter by upstream provider (e.g. github)")
310		cmd.Flags().StringVar(&owner, "owner", "", "filter by upstream owner login")
311		cmd.Flags().BoolVar(&showAvailable, "show-available", false, "instead of existing mirrors, list GitHub repos you could onboard as mirrors (ignores --cluster/--provider)")
312		return cmd
313	}
