332	func newRepoMirrorRemoveCmd() *cobra.Command {
333		return &cobra.Command{
334			Use:   "remove <github-url> [cluster-host]",
335			Short: "Un-register a GitHub mirror from a cluster",
336			Long: "Removes a mirror placement for a GitHub repo from the target " +
337				"cluster. Other clusters' placements of the same upstream are " +
338				"unaffected. The cluster-host defaults to " + defaultClusterHost +
339				" when omitted.",
340			Example: "  entire repo mirror remove github.com/octocat/hello-world",
341			Args:    cobra.RangeArgs(1, 2),
342			RunE: func(cmd *cobra.Command, args []string) error {
343				owner, repo, err := parseGitHubURL(args[0])
344				if err != nil {
345					cmd.SilenceUsage = true
346					return fmt.Errorf("invalid <github-url>: %w", err)
347				}
348				clusterHost := clusterArg(args)
349				if err := validateClusterHost(clusterHost); err != nil {
350					cmd.SilenceUsage = true
351					return fmt.Errorf("invalid [cluster-host]: %w", err)
352				}
353				return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
354					// Delete by upstream coords in one call. A 404 is a real
355					// error here, not idempotent success: the server only
356					// answers 204 when it actually removed a placement, so a
357					// 404 ("no such mirror / not visible / different cluster")
358					// surfaces verbatim via renderCoreError rather than being
359					// reported as a successful removal.
360					if err := c.DeleteMirror(ctx, coreapi.DeleteMirrorParams{
361						Provider:    coreapi.DeleteMirrorProviderGithub,
362						Owner:       owner,
363						Repo:        repo,
364						ClusterHost: clusterHost,
365					}); err != nil {
366						return err
367					}
368					cmd.Printf("Removed mirror github.com/%s/%s from %s\n", owner, repo, clusterHost)
369					return nil
370				})
371			},
372		}
373	}
