125	// style applies s to text only when color is enabled; otherwise it returns
126	// text unchanged so padding math and plain output stay correct.
127	func (t tableStyles) style(s lipgloss.Style, text string) string {
128		if !t.enabled {
129			return text
130		}
131		return s.Render(text)
132	}
133	
134	// columnStyle picks the foreground for a data cell: the first column is the
135	// primary identifier (white), the rest are secondary (gray).
136	func (t tableStyles) columnStyle(col int) lipgloss.Style {
137		if col == 0 {
138			return t.primary
139		}
140		return t.cell
141	}
