211	// writeTableRow pads each cell to its column width on the plain text, then
212	// styles it — so alignment is computed before any ANSI codes are added.
213	// The final column isn't padded, avoiding trailing whitespace.
214	func writeTableRow(b *strings.Builder, cells []string, widths []int, styleFor func(col int) lipgloss.Style, st tableStyles) {
215		for i, c := range cells {
216			last := i == len(cells)-1
217			padded := c
218			if !last && i < len(widths) {
219				padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
220			}
221			b.WriteString(st.style(styleFor(i), padded))
222			if !last {
223				b.WriteString("  ")
224			}
225		}
226		b.WriteByte('\n')
227	}
