package coreapi

import (
	"context"
	"log/slog"
	"net/http"

	"github.com/danielgtaylor/huma/v2"

	"entire.io/api/corev1"
	"entire.io/core/api"
	"entire.io/slogutil"
)

// ClusterService backs GET /api/v1/clusters.
type ClusterService struct {
	Server *api.Server
}

// ListClusters returns the data-plane clusters attached to this control
// plane, across all jurisdictions. Read-only and addressing-only: the
// internal mTLS endpoint is never surfaced. Requires authentication but no
// per-cluster authz — cluster topology is shared infrastructure, not a
// per-tenant resource.
func (s *ClusterService) ListClusters(ctx context.Context, _ *struct{}) (*corev1.ListClustersOutput, error) {
	if api.ClaimsFromContext(ctx) == nil {
		return nil, unauthorized("authentication required")
	}
	clusters, err := s.Server.ActiveClusters(ctx)
	if err != nil {
		slogutil.Error(ctx, "ListClusters failed", slog.Any("error", err))
		return nil, internalErr()
	}
	out := &corev1.ListClustersOutput{}
	out.Body.Clusters = make([]corev1.Cluster, 0, len(clusters))
	for _, c := range clusters {
		out.Body.Clusters = append(out.Body.Clusters, corev1.Cluster{
			Slug:         c.Slug,
			Jurisdiction: c.Jurisdiction,
			PublicURL:    c.PublicURL,
			IsDefault:    c.IsDefault,
		})
	}
	return out, nil
}

func registerClusterOperations(api huma.API, svc *ClusterService) {
	huma.Register(api, huma.Operation{
		OperationID: "listClusters",
		Method:      http.MethodGet,
		Path:        "/clusters",
		Summary:     "List data-plane clusters attached to this control plane",
		Tags:        []string{"clusters"},
		Security:    securityAny,
		Errors:      commonErrors,
	}, svc.ListClusters)
}

