package corev1

// Cluster is the wire representation of a data-plane cluster: the
// addressing info a client needs to reach an entire-server deployment.
// The internal mTLS endpoint is intentionally not exposed.
type Cluster struct {
	Slug         string `json:"slug"`
	Jurisdiction string `json:"jurisdiction"`
	PublicURL    string `json:"publicUrl"`
	IsDefault    bool   `json:"isDefault"`
}

// ListClustersOutput is the response for GET /api/v1/clusters.
type ListClustersOutput struct {
	Body struct {
		Clusters []Cluster `json:"clusters"`
	}
}

