// Package coreapi serves the user-facing JSON API of entire-core under
// /api/v1, using huma's code-first OpenAPI generator. The contract
// types live in api/corev1; this package wires the operations onto a
// humago adapter and bridges into the existing core/api.Server for
// business logic.
//
// Companion to server/repoapi which serves the data plane's repo API
// the same way. Both surfaces share OpenAPI 3.1, RFC 7807 problem+json
// errors, and /api/v1/{openapi.json,docs} doc paths.
package coreapi

import (
	"context"
	"log/slog"
	"net/http"
	"strings"

	"github.com/danielgtaylor/huma/v2"
	"github.com/danielgtaylor/huma/v2/adapters/humago"

	"entire.io/api/corev1"
	"entire.io/core/api"
	"entire.io/core/authn"
	"entire.io/slogutil"
	"entire.io/version"
)

// init configures huma's package-global schema toggles once at package
// load. Doing this inside NewHandler creates a data race when multiple
// parallel tests (or callers) construct handlers concurrently — the race
// detector flags the repeated writes even though the values never change.
//
// DefaultArrayNullable=false drops the JSON-Schema 2020-12 type-union
// shorthand (`"type": ["array","null"]`) huma emits for Go slice fields,
// so arrays serialize as plain `"type": "array"`. Scalar-`type` clients
// (ogen, which generates our CLI) reject the union form. Handlers must
// return non-nil slices for non-omitempty array fields so an absent
// collection serializes as `[]`, never `null` — the schema now forbids
// `null`. This is process-global; entire-core and entire-server run as
// separate binaries, so only the binary that imports this package is
// affected.
//
//nolint:gochecknoinits // huma's schema toggles are package-global; must be set before first handler construction.
func init() {
	huma.ValidateStrictCasing = true
	huma.DefaultArrayNullable = false
}

// NewHandler builds the entire-core OpenAPI HTTP handler. Runtime docs
// and spec routes are public; every operation route requires a valid
// principal (verified by core/api.AuthMiddleware which runs upstream).
// State-changing operations additionally require a full session
// credential — narrowed api-access tokens (no entire:session scope) can
// read but never mutate; they're rejected the same way api.RequireSession
// rejects them on the legacy mux (COR-273).
//
// The huma.API is passed to authMW so authentication failures render as
// the same problem+json envelope as operation errors.
func NewHandler(srv *api.Server) http.Handler {
	mux := http.NewServeMux()
	cfg := huma.DefaultConfig("Entire Core API", "1.0.0")
	cfg.OpenAPI.Info.Description = "Entire control plane: identity, orgs, projects, repos, mirrors, service accounts."
	cfg.RejectUnknownQueryParameters = true
	// additionalProperties:true so clients tolerate fields the server adds
	// before they regenerate. Query-param strictness above is unaffected.
	cfg.AllowAdditionalPropertiesByDefault = true
	// Relative server URL — SDK generators resolve operation paths
	// against whichever jurisdiction's spec they fetched (e.g.
	// https://us.auth.entire.io/api/v1/openapi.json picks up us.auth.entire.io),
	// so we don't need to enumerate jurisdictions or environments here.
	cfg.OpenAPI.Servers = []*huma.Server{{URL: "/api/v1"}}
	addSecuritySchemes(cfg.OpenAPI)

	humaAPI := humago.NewWithPrefix(mux, "/api/v1", cfg)

	registerVersionOperation(humaAPI, srv)
	registerIdentityOperations(humaAPI, &IdentityService{Server: srv})
	registerOrgOperations(humaAPI, &OrgService{Server: srv})
	registerProjectOperations(humaAPI, &ProjectService{Server: srv})
	registerRepoOperations(humaAPI, &RepoService{Server: srv})
	registerMirrorOperations(humaAPI, &MirrorService{Server: srv})
	registerServiceAccountOperations(humaAPI, &ServiceAccountService{Server: srv})
	registerClusterOperations(humaAPI, &ClusterService{Server: srv})

	authMW := requirePrincipal(func(r *http.Request) (int, string) {
		claims := api.ClaimsFromContext(r.Context())
		if claims == nil {
			return http.StatusUnauthorized, "authentication required"
		}
		if isMutation(r) && !claims.HasScope(authn.ScopeEntireSession) {
			// Distinguish this token-shape denial from per-handler
			// SpiceDB 403s — when a narrowed token unexpectedly hits a
			// mutation in prod, this line is the diagnostic.
			slogutil.Warn(r.Context(), "coreapi: non-session token denied on mutation",
				slog.String("method", r.Method),
				slog.String("path", r.URL.Path),
				slog.Any("scope", claims.Scope))
			return http.StatusForbidden, "this route requires a session credential"
		}
		return 0, ""
	})

	// recordRoute dispatches to the huma mux, then records the matched
	// per-operation route so the outer core/api span can template http.route
	// to the operation. The mux populates r.Pattern (e.g. "GET /api/v1/version")
	// in place during dispatch; OTel http.route is the path template without the
	// method, so the prefix is stripped. The slot is reachable because core/api
	// seeds it outside otelhttp (see api.RecordedRoute) and the pointer survives
	// the request clones the auth layers make.
	//
	// Only a match records: an unmatched path (404) or method mismatch (405)
	// leaves r.Pattern empty, so the span keeps the "/api/v1/" catch-all rather
	// than a route. The slot is freshly seeded per request, so leaving it unset
	// can't surface a stale route from an earlier one.
	recordRoute := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mux.ServeHTTP(w, r)
		if r.Pattern != "" {
			api.RecordedRouteFrom(r.Context()).Set(strings.TrimPrefix(r.Pattern, r.Method+" "))
		}
	})

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if isPublicDocsPath(r.URL.Path) {
			recordRoute.ServeHTTP(w, r)
			return
		}
		authMW(humaAPI, recordRoute).ServeHTTP(w, r)
	})
}

// isMutation reports whether the request can change state and must
// therefore carry session authority. Method-based so a newly registered
// operation is gated by default — there is no per-route flag to forget.
// POST /lookup is the one read that uses a mutating method (POST only to
// carry its batch body); it stays open to api-access tokens like every
// other read. The exemption is pinned to POST so another method
// registered at that path would still be gated.
func isMutation(r *http.Request) bool {
	switch r.Method {
	case http.MethodGet, http.MethodHead:
		return false
	}
	return r.Method != http.MethodPost || r.URL.Path != "/api/v1/lookup"
}

// isPublicDocsPath returns true for the OpenAPI spec + docs UI routes
// that should be reachable without authentication. Includes huma's
// OpenAPI 3.0 downgrade variants so SDK generators that don't speak
// 3.1 yet can still fetch a spec.
func isPublicDocsPath(path string) bool {
	switch path {
	case "/api/v1/openapi.json",
		"/api/v1/openapi.yaml",
		"/api/v1/openapi-3.0.json",
		"/api/v1/openapi-3.0.yaml",
		"/api/v1/openapi-3.1.json",
		"/api/v1/openapi-3.1.yaml",
		"/api/v1/docs",
		// Version is the server half of `entire-core version`; public so
		// the CLI can report the server build without a session.
		"/api/v1/version":
		return true
	}
	return strings.HasPrefix(path, "/api/v1/docs/") || strings.HasPrefix(path, "/api/v1/schemas/")
}

// registerVersionOperation wires GET /api/v1/version — an unauthenticated
// endpoint reporting the running binary's commit and mode. No Security
// clause: it's listed in isPublicDocsPath so the auth wrapper lets it
// through, matching `kubectl version`'s reachable-without-credentials
// server probe.
func registerVersionOperation(humaAPI huma.API, srv *api.Server) {
	huma.Register(humaAPI, huma.Operation{
		OperationID: "getVersion",
		Method:      http.MethodGet,
		Path:        "/version",
		Summary:     "Get the server version and mode",
		Tags:        []string{"meta"},
		Errors:      []int{http.StatusInternalServerError},
	}, func(_ context.Context, _ *struct{}) (*corev1.GetVersionOutput, error) {
		out := &corev1.GetVersionOutput{}
		out.Body.Version = version.FullCommit
		out.Body.Mode = srv.Mode()
		return out, nil
	})
}

// addSecuritySchemes declares the OpenAPI security schemes that document
// which auth methods individual operations accept. Enforcement happens
// in the upstream core/api.AuthMiddleware and the authMW wrapper above —
// the schemes themselves are documentation-only, but tagging each
// operation with Security: [...] makes /api/v1/docs render an auth
// picker and tells SDK generators what to wire up.
func addSecuritySchemes(spec *huma.OpenAPI) {
	if spec.Components == nil {
		spec.Components = &huma.Components{}
	}
	if spec.Components.SecuritySchemes == nil {
		spec.Components.SecuritySchemes = map[string]*huma.SecurityScheme{}
	}
	spec.Components.SecuritySchemes["bearerAuth"] = &huma.SecurityScheme{
		Type:         "http",
		Scheme:       "bearer",
		BearerFormat: "JWT",
		Description:  "Bearer token minted by entire-core's device-code flow or STS exchange.",
	}
	spec.Components.SecuritySchemes["sessionAuth"] = &huma.SecurityScheme{
		Type:        "apiKey",
		In:          "cookie",
		Name:        "entire_session",
		Description: "Console session cookie issued by the browser login flow.",
	}
}

// securityAny is the standard Security clause for operations that
// accept either a bearer JWT or a session cookie. Either suffices.
var securityAny = []map[string][]string{
	{"bearerAuth": {}},
	{"sessionAuth": {}},
}

// commonErrors are the HTTP status codes that almost every operation
// might return. Per-operation registrations add 404/409/etc. as needed.
var commonErrors = []int{
	http.StatusBadRequest,
	http.StatusUnauthorized,
	http.StatusForbidden,
	http.StatusInternalServerError,
}

